def longest_common_prefix(strs):
    if not strs:
        return ""

    # Use the first string as reference
    prefix = strs[0]

    for s in strs[1:]:
        # Shorten prefix until it's a prefix of s
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""

    return prefix

# Test cases
tests = [
    (["flower","flow","flight"], "fl"),
    (["dog","racecar","car"], ""),
    (["interview","intermediate","internal"], "inter"),
    ([], ""),
]

for strs, expected in tests:
    result = longest_common_prefix(strs)
    status = "PASS" if result == expected else "FAIL"
    print(f"{status}: {strs} -> {result!r} (expected {expected!r})")

