import re

def decode_run_length(s):
    return ''.join(int(count) * char for count, char in re.findall(r'(\d+)(.)', s))

tests = [
    ("3a2b", "aaabb"),
    ("1x5y0z", "xyyyyy"),
    ("10*", "**********"),
    ("", ""),
]

for inp, expected in tests:
