    print(f"{inp!r:10} -> {result!r:15} expected {expected!r:15} {'OK' if result == expected else 'FAIL'}")

def generate_parentheses(n):
    result = []

    def backtrack(s, open_count, close_count):
        if len(s) == 2 * n:
            result.append(s)
            return
        if open_count < n:
            backtrack(s + "(", open_count + 1, close_count)
        if close_count < open_count:
            backtrack(s + ")", open_count, close_count + 1)

    backtrack("", 0, 0)
    return result

# Test cases
for n in range(1, 5):
    res = generate_parentheses(n)
    print(n, res)
    # verify correctness
    assert len(res) == len(set(res)), "duplicates found"
    for s in res:
        assert len(s) == 2 * n
        bal = 0
        for ch in s:
            bal += 1 if ch == "(" else -1
            assert bal >= 0, f"invalid prefix in {s}"
        assert bal == 0, f"unbalanced {s}"

print("All tests passed")

