def is_perfect(n):
    if n <= 1:
        return False
    total = 1  # 1 is a proper divisor for n>1
    import math
    limit = int(math.isqrt(n))
    for d in range(2, limit+1):
        if n % d == 0:
            total += d
            other = n // d
            if other != d:
                total += other
    return total == n

# Test cases
tests = [6, 28, 12, 496, 1]
for t in tests:
