    end = min(a_end, b_end)
    if start > end:
        return None
    return (start, end)

# Test cases
print(range_intersect(1, 5, 3, 7))   # (3, 5)
print(range_intersect(1, 3, 5, 7))   # None
print(range_intersect(1, 10, 3, 5))  # (3, 5)
print(range_intersect(5, 5, 5, 5))   # (5, 5)

