def encode_rle(s):
    if not s:
        return ''
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            result.append(f"{count}{s[i-1]}")
            count = 1
    result.append(f"{count}{s[-1]}")
    return ''.join(result)

# Test cases
tests = [
    ('aaabbc', '3a2b1c'),
    ('', ''),
    ('a', '1a'),
    ('aaaa', '4a'),
]

for inp, expected in tests:
    out = encode_rle(inp)
    status = "PASS" if out == expected else "FAIL"
    print(f"{status}: encode_rle({inp!r}) = {out!r} (expected {expected!r})")

