{"code": "import re

def decode_rle(s):
    if not s:
        return ''
    result = []
    # Match runs of digits followed by a character
    for count, char in re.findall(r'(\d+)([a-zA-Z])', s):
        result.append(char * int(count))
    return ''.join(result)

# Test cases
print(repr(decode_rle('3a2b1c')))  # 'aaabbc'
print(repr(decode_rle('')))        # ''
print(repr(decode_rle('1a')))      # 'a'
print(repr(decode_rle('4a')))      # 'aaaa'
